#include <bits/stdc++.h>
using namespace std;
struct E{int kind,s,l,m,e,g;}; struct C{E a,b;int cap,margin,pen,block,mode;};struct R{double w,dd;int orders;};
struct State{E e;int want=0,trend=0,mr=0,prev=0,exec=0,score=0;long long ss=0,sl=0,sm=0;int signal(vector<int>const&p,int i){int x=p[i];ss+=x-(i>=e.s?p[i-e.s]:0);sl+=x-(i>=e.l?p[i-e.l]:0);sm+=x-(i>=60?p[i-60]:0);if(i+1<max(e.l,e.kind==0?60:1))return 0;long long d=ss*e.l-sl*e.s,D=e.s*e.l; switch(e.kind){case 0:if(d>e.m*D)trend=1;else if(d<-e.m*D)trend=0;if(x*60-sm<-240)mr=1;else if(x*60-sm>0)mr=0;want=trend||(mr&&d>=-e.g*D);break;case 1: if(x*e.l-sl<-e.m*e.l)want=1;else if(x*e.l-sl>e.e*e.l)want=0;break;case 2:if(d>e.m*D)want=1;else if(d<-e.e*D)want=0;break;case 3:if(d<-e.m*D)want=1;else if(d>e.e*D)want=0;break;case 4:want=0;break;case 5:want=1;break;}return want;}};
R run(const vector<int>&p,C c){State a{c.a},b{c.b};int cash=10000,sh=0,pend=0,peak=10000,orders=0,choice=0,score=0;double dd=0;for(int i=0;i<p.size();i++){int x=p[i],n=0;if(pend==1){n=min(63,max(0,(cash-5)/x));if(n){cash-=n*x+5;sh+=n;orders++;}}else if(pend==2){n=min(63,sh);if(n&&cash+n*x>=5){cash+=n*x-5;sh-=n;orders++;}}int w=cash+sh*x;peak=max(peak,w);dd=max(dd,double(peak-w)/peak);
if(i){int delta=x-p[i-1];score+=16*(a.exec-b.exec)*delta-c.pen*(abs(a.prev-a.exec)-abs(b.prev-b.exec));score=max(-c.cap,min(c.cap,score));if(c.block&&i%c.block==0)score/=2;}
a.exec=a.prev;b.exec=b.prev;a.prev=a.signal(p,i);b.prev=b.signal(p,i);if(score>c.margin)choice=0;else if(score<-c.margin)choice=1;int want=choice?b.prev:a.prev;if(c.mode==1&&abs(score)<=c.margin)want=a.prev&&b.prev;if(c.mode==2&&abs(score)<=c.margin)want=a.prev||b.prev;pend=want?1:2;}return{double(cash+sh*p.back()),dd,orders};}
vector<int>read(string f){ifstream in(f);string s;getline(in,s);vector<int>p;while(getline(in,s))if(s.size())p.push_back(stoi(s.substr(s.find(',')+1)));return p;}
int main(){auto a=read("tb/practica.csv"),b=read("tb/practica_meta.csv");vector<vector<int>> tr;for(auto p:{a,b})for(int i=0;i<12000;i+=3000)tr.emplace_back(p.begin()+i,p.begin()+i+3000);E base{0,20,120,8,0,4};vector<E>ex{{0,20,120,8,0,4},{0,16,64,4,0,4},{0,20,120,4,0,8},{1,1,16,2,0,0},{1,1,32,3,0,0},{1,1,60,4,0,0},{1,1,60,4,2,0},{1,1,120,6,0,0},{2,8,32,2,0,0},{2,20,120,4,0,0},{2,20,120,8,4,0},{3,8,48,3,0,0},{4,1,1,0,0,0},{5,1,1,0,0,0}};vector<C> cs;for(int a=0;a<ex.size()-1;a++)for(int b=a+1;b<ex.size();b++)for(int cap:{64,128,256,512})for(int m:{0,16,32,64})if(m<cap)for(int block:{0})for(int mode:{0,1})cs.push_back({ex[a],ex[b],cap,m,2,block,mode});vector<pair<double,int>> rs;for(int k=0;k<cs.size();k++){double s[2]={};for(int i=0;i<8;i++){auto r=run(tr[i],cs[k]);s[i/4]+=(log(max(1.,r.w)/10000.)-.5*r.dd)/4;}rs.push_back({(s[0]+s[1])/2-.6*abs(s[0]-s[1]),k});}sort(rs.rbegin(),rs.rend());auto show=[&](C c,double sc){cout<<sc<<" A "<<c.a.kind<<" "<<c.a.s<<" "<<c.a.l<<" "<<c.a.m<<" "<<c.a.e<<" "<<c.a.g<<" B "<<c.b.kind<<" "<<c.b.s<<" "<<c.b.l<<" "<<c.b.m<<" "<<c.b.e<<" "<<c.b.g<<" cap/m/mode "<<c.cap<<" "<<c.margin<<" "<<c.mode;for(auto p:{a,b}){auto r=run(p,c);vector<int>h(p.begin()+12000,p.end());auto t=run(h,c);cout<<" full "<<r.w<<" "<<r.dd<<" test "<<t.w<<" "<<t.dd;}cout<<"\n";};show({base,base,128,0,2,0,0},0);for(int i=0;i<20;i++)show(cs[rs[i].second],rs[i].first);}
